"""
Tugas Praktik 03: Kalkulator Anggaran Daya Tautan (Link Budget)
"""
def hitung_link_budget(p_tx_dbm: float, g_tx_dbi: float, g_rx_dbi: float, l_fspl_db: float, l_misc_db: float) -> dict:
    p_rx = p_tx_dbm + g_tx_dbi + g_rx_dbi - l_fspl_db - l_misc_db
    margin = p_rx - (-95.0)
    return {'p_rx': p_rx, 'margin': margin, 'layak': margin >= 10.0}

if __name__ == '__main__':
    print(hitung_link_budget(43.0, 18.0, 14.0, 142.5, 3.0))
